// 26 進位轉換（A=1 ... Z=26）
// 時間複雜度: O(n)，空間複雜度: O(1)
function titleToNumber(columnTitle) {
    let result = 0;
    for (const ch of columnTitle) {
        result = result * 26 + (ch.charCodeAt(0) - 64); // 'A' 的字元碼是 65
    }
    return result;
}

