#include <string>
using namespace std;

class Solution {
public:
    /**
     * 進制轉換
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int titleToNumber(string columnTitle) {
        int result = 0;

        for (char c : columnTitle) {
            int value = c - 'A' + 1;
            result = result * 26 + value;
        }

        return result;
    }
};

